function creerFilePriorite() {
  const heap = [];

  function parent(index) { return Math.floor((index - 1) / 2); }
  function gauche(index) { return 2 * index + 1; }
  function droite(index) { return 2 * index + 2; }

  function percolerHaut(index) {
    while (index > 0 && heap[parent(index)][1] > heap[index][1]) {
      [heap[parent(index)], heap[index]] = [heap[index], heap[parent(index)]];
      index = parent(index);
    }
  }

  function percolerBas(index) {
    const len = heap.length;
    while (gauche(index) < len) {
      let minIndex = gauche(index);
      if (droite(index) < len && heap[droite(index)][1] < heap[minIndex][1]) {
        minIndex = droite(index);
      }
      if (heap[index][1] <= heap[minIndex][1]) break;
      [heap[index], heap[minIndex]] = [heap[minIndex], heap[index]];
      index = minIndex;
    }
  }

  return {
    enqueue: function(val, priorite) {
      heap.push([val, priorite]);
      percolerHaut(heap.length - 1);
    },
    dequeue: function() {
      if (heap.length === 0) return null;
      const min = heap[0];
      const last = heap.pop();
      if (heap.length > 0) {
        heap[0] = last;
        percolerBas(0);
      }
      return min[0];
    },
    taille: function() { return heap.length; }
  };
}
