async function executerEnPool(taches, concurrence) {
  const results = new Array(taches.length);
  const executing = [];

  for (let i = 0; i < taches.length; i++) {
    const task = Promise.resolve().then(() => taches[i]());
    results[i] = task;

    if (executing.length >= concurrence) {
      await Promise.race(executing).finally(() => {
        executing.splice(executing.indexOf(Promise.race(executing)), 1);
      });
    }

    executing.push(task);
  }

  const settledResults = await Promise.allSettled(results);

  return settledResults.map(result => result.status === 'fulfilled' ? result.value : null);
}
