function creerSubject() {
  const subscribers = [];
  let isCompleted = false;
  let hasErrorOccurred = false;

  function subscribe({ next, error, complete }) {
    if (hasErrorOccurred) {
      error(subscribers[0].error);
    } else if (isCompleted) {
      complete();
    } else {
      subscribers.push({ next, error, complete });
    }
  }

  function next(value) {
    if (!isCompleted && !hasErrorOccurred) {
      for (const subscriber of subscribers.slice()) {
        subscriber.next(value);
      }
    }
  }

  function error(err) {
    if (!isCompleted && !hasErrorOccurred) {
      hasErrorOccurred = true;
      for (const subscriber of subscribers.slice()) {
        subscriber.error(err);
      }
      subscribers.length = 0; // Clear all subscribers
    }
  }

  function complete() {
    if (!isCompleted && !hasErrorOccurred) {
      isCompleted = true;
      for (const subscriber of subscribers.slice()) {
        subscriber.complete();
      }
      subscribers.length = 0; // Clear all subscribers
    }
  }

  return { subscribe, next, error, complete };
}

function memoiserAsync(fn) {
  const cache = new Map();

  return async function(...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) {
      return await cache.get(key);
    }

    let promise = fn.apply(this, args);
    cache.set(key, promise);

    try {
      const result = await promise;
      cache.delete(key); // Remove from cache after resolution
      return result;
    } catch (error) {
      cache.delete(key); // Remove from cache on error
      throw error;
    }
  };
}

