# PowerShell script deploy-patch.ps1 with Copy-Item backup + sqlite3 + rollback on error

function Deploy-Patch {
    param (
        [string]$PatchFile,
        [string]$BackupDir,
        [string]$DatabasePath
    )

    try {
        # Backup current state using Copy-Item
        $backupFile = Join-Path -Path $BackupDir -ChildPath (Split-Path -Leaf $PatchFile)
        Copy-Item -Path $PatchFile -Destination $backupFile

        # Apply patch and update database
        & sqlite3 $DatabasePath ".read $PatchFile"

    } catch {
        Write-Host "Error occurred: $_"

        # Rollback to backup on error
        if (Test-Path $backupFile) {
            Copy-Item -Path $backupFile -Destination $PatchFile -Force
            & sqlite3 $DatabasePath ".read $backupFile"
        }
    } finally {
        Write-Host "Deployment process completed."
    }
}
