function rotationDroite(tab, k) {
    const n = tab.length;
    k %= n;

    function reverse(arr, start, end) {
        while (start < end) {
            [arr[start], arr[end]] = [arr[end], arr[start]];
            start++;
            end--;
        }
    }

    reverse(tab, 0, n - 1);
    reverse(tab, 0, k - 1);
    reverse(tab, k, n - 1);

    return tab;
}
